/**
 * Study RAG — TF-IDF retriever (client-side, dependency-free).
 * Operates on window.GA_STUDY_KNOWLEDGE (generated by Analytics).
 */
window.GAStudyRag = (() => {
  const TOKEN_RE = /[a-zA-ZÀ-ÿ0-9][a-zA-ZÀ-ÿ0-9_'-]*/gu;

  function normalize(text) {
    return (text || "").toLowerCase().match(TOKEN_RE) || [];
  }

  class RagIndex {
    constructor(records) {
      this.records = [];
      this.docTokens = [];
      this.docTf = [];
      this.idf = {};
      this.docNorms = [];

      records = records || [];
      for (let i = 0; i < records.length; i++) {
        const record = records[i];
        const normalized = {
          key: String(record.key || record.id || `node-${i}`),
          label: String(record.label || ""),
          type: String(record.type || "concept"),
          aliases: Array.isArray(record.aliases) ? record.aliases : [],
          description: String(record.description || ""),
        };
        this.records.push(normalized);

        const searchText = [
          normalized.label,
          normalized.type,
          normalized.description,
          normalized.aliases.join(" "),
        ]
          .join(" ")
          .toLowerCase();
        const tokens = searchText.match(TOKEN_RE) || [];
        this.docTokens.push(tokens);
      }

      // Build TF
      for (let i = 0; i < this.docTokens.length; i++) {
        const tf = {};
        for (const token of this.docTokens[i]) {
          tf[token] = (tf[token] || 0) + 1;
        }
        this.docTf.push(tf);
      }

      // Build IDF
      const n = Math.max(1, records.length);
      const df = {};
      for (const tokens of this.docTokens) {
        const unique = new Set(tokens);
        for (const token of unique) {
          df[token] = (df[token] || 0) + 1;
        }
      }
      for (const term in df) {
        this.idf[term] = Math.log((n + 1) / (df[term] + 1)) + 1.0;
      }

      // Build doc norms
      for (const tf of this.docTf) {
        let norm = 0;
        for (const term in tf) {
          const idf = this.idf[term] || 1.0;
          norm += (tf[term] * idf) ** 2;
        }
        this.docNorms.push(Math.sqrt(norm) || 1.0);
      }
    }

    search(query, options) {
      options = options || {};
      const topK = options.limit || 6;
      const minScore = options.minScore || 0.05;

      const qTokens = normalize(query);
      if (qTokens.length === 0) {
        return [];
      }

      const qTf = {};
      for (const token of qTokens) {
        qTf[token] = (qTf[token] || 0) + 1;
      }

      let qNorm = 0;
      for (const term in qTf) {
        const idf = this.idf[term] || 1.0;
        qNorm += (qTf[term] * idf) ** 2;
      }
      qNorm = Math.sqrt(qNorm);

      const normalized = qTokens.join(" ");
      const scored = [];

      for (let i = 0; i < this.records.length; i++) {
        const record = this.records[i];
        const dTf = this.docTf[i];
        const dNorm = this.docNorms[i];

        let dot = 0;
        for (const term in qTf) {
          if (term in dTf) {
            const idf = this.idf[term] || 1.0;
            dot += (qTf[term] * idf) * (dTf[term] * idf);
          }
        }
        let score = qNorm > 0 ? dot / (qNorm * dNorm) : 0;

        // Alias/label boost
        const labelNorm = normalize(record.label).join(" ");
        if (labelNorm && normalized.includes(labelNorm)) {
          score += 0.65;
        }
        for (const alias of record.aliases) {
          const aliasNorm = normalize(alias).join(" ");
          if (aliasNorm && normalized.includes(aliasNorm)) {
            score += 0.45;
            break;
          }
        }

        if (score >= minScore) {
          scored.push([score, record]);
        }
      }

      scored.sort((a, b) => b[0] - a[0]);
      return scored.slice(0, topK).map(([score, record]) => ({
        nodeKey: record.key,
        label: record.label,
        type: record.type,
        score: Math.round(score * 10000) / 10000,
        match: "tfidf+alias",
      }));
    }
  }

  function create(knowledge) {
    return new RagIndex(knowledge || []);
  }

  return { create };
})();
